// Package uiform builds huh forms wired to Entire's standard theme and
// accessibility behavior. Centralises the Theme()+WithAccessible() recipe
// so picker UI stays consistent across callers.
package uiform

import (
	"context"
	"errors"
	"fmt"
	"os"

	"charm.land/huh/v2"
	"charm.land/lipgloss/v2"

	"github.com/entireio/cli/cmd/entire/cli/palette"
)

// IsAccessibleMode reports whether accessibility mode is enabled via the
// ACCESSIBLE environment variable. Set ACCESSIBLE=1 (or any non-empty
// value) to enable simpler prompts that work better with screen readers.
func IsAccessibleMode() bool {
	return os.Getenv("ACCESSIBLE") != ""
}

// Theme returns Entire's standard huh theme: base16 (ANSI 0–15) colors so
// form prompts respect the user's terminal palette and stay consistent with
// the rest of the CLI's styling. Derived from huh.ThemeBase16 with a few
// overrides — magenta selection (pointer + chosen options); titles and
// unselected options use the terminal's default foreground so they invert
// with the background (dark text on light, light text on dark) like the
// checkbox bracket does.
func Theme() huh.Theme {
	return huh.ThemeFunc(func(isDark bool) *huh.Styles {
		t := huh.ThemeBase16(isDark)

		accent := lipgloss.Color(palette.Accent)
		lightDark := lipgloss.LightDark(isDark)

		// Titles and unselected options drop their explicit color and inherit
		// the terminal's default text color, which already inverts with the
		// background. A pinned base16 slot (e.g. black "0") can't invert because
		// it always maps to that slot in both themes. Group.Title is copied from
		// Focused.Title inside ThemeBase16, and ThemeBase16 copies Focused into
		// Blurred wholesale, so clear the blurred variants too — otherwise
		// inactive fields in multi-field forms keep the pinned base16 color.
		t.Focused.Title = t.Focused.Title.UnsetForeground()
		t.Group.Title = t.Group.Title.UnsetForeground()
		t.Focused.UnselectedOption = t.Focused.UnselectedOption.UnsetForeground()
		t.Blurred.Title = t.Blurred.Title.UnsetForeground()
		t.Blurred.UnselectedOption = t.Blurred.UnselectedOption.UnsetForeground()

		// Magenta selection: the pointer (single + multi select) and the
		// chosen option(s), replacing ThemeBase16's yellow/green.
		t.Focused.SelectSelector = t.Focused.SelectSelector.Foreground(accent)
		t.Focused.MultiSelectSelector = t.Focused.MultiSelectSelector.Foreground(accent)
		t.Focused.SelectedOption = t.Focused.SelectedOption.Foreground(accent)
		t.Focused.SelectedPrefix = t.Focused.SelectedPrefix.Foreground(accent)

		// Blurred (inactive) button: no background chip and default text color,
		// so it reads as plain text that inverts with the terminal theme while
		// the focused button keeps its magenta/accent chip. Set both the focused
		// and blurred field variants (ThemeBase16 copies Focused into Blurred).
		t.Focused.BlurredButton = t.Focused.BlurredButton.UnsetForeground().UnsetBackground()
		t.Blurred.BlurredButton = t.Blurred.BlurredButton.UnsetForeground().UnsetBackground()

		// Focused (selected) button: keep the magenta chip, but use the inverse
		// of the default foreground — i.e. the terminal's background color — so
		// the label reads as reverse video against the chip (light on light
		// terminals, black on dark), the opposite of the unset blurred button.
		buttonText := lightDark(lipgloss.Color(palette.BrightWhite), lipgloss.Color(palette.Black))
		t.Focused.FocusedButton = t.Focused.FocusedButton.Foreground(buttonText)
		t.Blurred.FocusedButton = t.Blurred.FocusedButton.Foreground(buttonText)

		return t
	})
}

// New creates a huh form with the standard theme, switching to accessible
// mode when ACCESSIBLE is set. WithAccessible is only available on forms
// (not individual fields), so wrap confirmations and other prompts in a
// form to opt into accessibility.
func New(groups ...*huh.Group) *huh.Form {
	form := huh.NewForm(groups...).WithTheme(Theme())
	if IsAccessibleMode() {
		form = form.WithAccessible(true)
	}
	return form
}

// PromptYN renders a Confirm form with the standard theme/accessibility
// behavior and returns the user's answer. On user cancellation (Ctrl+C or
// context.Canceled) returns (false, nil) so callers treat it as a "no";
// on real form errors the error is returned wrapped.
func PromptYN(ctx context.Context, question string, def bool) (bool, error) {
	answer := def
	form := New(huh.NewGroup(
		huh.NewConfirm().
			Title(question).
			Value(&answer),
	))
	if err := form.RunWithContext(ctx); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
			return false, nil
		}
		return false, fmt.Errorf("confirm form: %w", err)
	}
	return answer, nil
}

// Package interactive provides TTY-related helpers shared between the cli
// and strategy packages without inducing an import cycle (strategy cannot
// import cli).
package interactive

import (
	"io"
	"os"
	"testing"

	"golang.org/x/term"
)

// EnvTestTTY is the env-var name for the force-interactive test override.
//   - EnvTestTTY=1 → CanPromptInteractively returns true.
//   - EnvTestTTY set to any other value → returns false.
//   - EnvTestTTY unset → real detection via testing.Testing(), agent
//     sentinels, CI, then /dev/tty probe.
const EnvTestTTY = "ENTIRE_TEST_TTY"

// CanPromptInteractively reports whether interactive confirmation prompts
// (huh forms, yes/no questions, etc.) can be shown. Returns false in CI,
// agent subprocesses that inherit a TTY but can't respond to prompts,
// and other environments without a controlling TTY.
//
// Precedence (first match wins):
//  1. EnvTestTTY=1 forces interactive ON; any other non-empty value forces OFF.
//  2. testing.Testing() — `go test` runs default to OFF so in-process tests
//     don't hang on developer terminals that happen to have a real /dev/tty.
//     Subprocess tests must spawn via execx.NonInteractive (or set EnvTestTTY).
//  3. Agent sentinels — vendor-set by agent subprocesses.
//  4. CI=<non-empty-non-false> — de-facto CI convention.
//  5. /dev/tty probe.
func CanPromptInteractively() bool {
	if v := os.Getenv(EnvTestTTY); v != "" {
		return v == "1"
	}
	if testing.Testing() {
		return false
	}
	if isAgentSubprocessEnv() {
		return false
	}
	// CI=<non-empty> is the de-facto CI-provider convention (GitHub Actions,
	// CircleCI, GitLab, Travis, Buildkite). Self-hosted runners expose /dev/tty,
	// so the probe below isn't enough — an interactive prompt on CI hangs.
	// CI=false is the `is-ci` escape hatch for developers who need to override
	// an inherited value.
	if v := os.Getenv("CI"); v != "" && v != "false" {
		return false
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return false
	}
	_ = tty.Close()
	return true
}

// UnderTest reports whether the process is running in a test context — either
// inside `go test` (testing.Testing()) or with EnvTestTTY explicitly set. Use
// to skip operations that read from the real terminal (e.g. opening /dev/tty)
// even when CanPromptInteractively() returns true.
func UnderTest() bool {
	return testing.Testing() || os.Getenv(EnvTestTTY) != ""
}

// isAgentSubprocessEnv reports whether the env indicates we're running inside
// an agent subprocess that inherited a TTY but can't respond to prompts:
//   - GEMINI_CLI=1: Gemini CLI shell tool (https://geminicli.com/docs/tools/shell/)
//   - COPILOT_CLI=1: Copilot CLI hook subprocesses (v0.0.421+)
//   - PI_CODING_AGENT=true: Pi Coding Agent shell tool
//   - GIT_TERMINAL_PROMPT=0: caller (CI, Factory AI Droid, etc.) asked git
//     to stop prompting; respect it from git-hook context too.
func isAgentSubprocessEnv() bool {
	return os.Getenv("GEMINI_CLI") != "" ||
		os.Getenv("COPILOT_CLI") != "" ||
		os.Getenv("PI_CODING_AGENT") != "" ||
		os.Getenv("GIT_TERMINAL_PROMPT") == "0"
}

// IsTerminalReader reports whether r is an *os.File backed by a terminal.
// It is useful when an explicitly interactive command needs to distinguish a
// human at stdin from an agent process that merely inherited a controlling TTY.
func IsTerminalReader(r io.Reader) bool {
	f, ok := r.(*os.File)
	if !ok {
		return false
	}
	return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

// IsTerminalWriter reports whether w is an *os.File backed by a terminal.
// Use for deciding on color, pager, progress bars, or other writer-scoped
// TTY formatting. For "can I prompt the user?" use CanPromptInteractively.
func IsTerminalWriter(w io.Writer) bool {
	f, ok := w.(*os.File)
	if !ok {
		return false
	}
	return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

// ShouldStyle reports whether ANSI-styled output (color, bold, rendered
// markdown) should be written to w. It is the single gate for writer-scoped
// styling decisions: NO_COLOR disables styling per https://no-color.org,
// legacy consoles that can't handle ANSI escapes are excluded, and otherwise
// the answer is whether w is a terminal.
func ShouldStyle(w io.Writer) bool {
	return shouldStyle(os.Getenv("NO_COLOR"), os.Getenv("TERM"), IsTerminalWriter(w))
}

// shouldStyle is the pure decision behind ShouldStyle, split out so tests can
// exercise the NO_COLOR/TERM gates with a simulated terminal writer — `go
// test` never has a real one, so testing through ShouldStyle would
// short-circuit on the terminal check and never reach the earlier gates.
func shouldStyle(noColor, term string, isTerminalWriter bool) bool {
	if noColor != "" {
		return false
	}
	if termLacksANSI(term) {
		return false
	}
	return isTerminalWriter
}

// termLacksANSI reports whether term identifies a legacy console that does
// not reliably handle ANSI escape sequences. The canonical case is
// TERM=cygwin: writing the ESC byte (0x1B) ends up rendered as the CP437
// glyph U+2190 LEFTWARDS ARROW ("←") instead of starting an SGR sequence, so
// styled output appears as literal text like "←[32m●←[m" (see GH #1267).
func termLacksANSI(term string) bool {
	return term == "cygwin"
}

