	}
	summary, err = store.Read(context.Background(), targetID)
	if err != nil {
		t.Fatal(err)
	}
	if len(summary.Sessions) != 1 {
		t.Errorf("retry duplicated the session: %d sessions, want 1", len(summary.Sessions))
	}
}

